        static void Need(bool b,string message){if(!b)throw new InvalidDataException(message);}
        static bool Same(byte[] a,byte[] b){if(a.Length!=b.Length)return false;for(int n=0;n<a.Length;n++)if(a[n]!=b[n])return false;return true;}
        static bool Reject(Action a){try{a();return false;}catch(ArgumentException){return true;}catch(InvalidDataException){return true;}catch(NotSupportedException){return true;}}
        internal static void Run(Action<string,Action> check)
        {
            check("Scenario position selection matches 2448 original numeric position and RNG vectors",delegate{Verify(false);});
            check("Position study copied fixtures match 306 original sparse pool inputs at seed731",delegate{Verify(true);});
            check("Scenario position selection preserves complete supplied pools and deterministic reset",delegate{
                var copy=new PracticeScenarioPositionCopy(18,2,731,8);var f=(byte[])copy.Fleets.Clone();var t=(byte[])copy.Terrain.Clone();f[7000]=123;t[7000]=45;var beforeF=(byte[])f.Clone();var beforeT=(byte[])t.Clone();var a=PracticeScenarioPositions.Select(18,2,731,f,t,128);var b=PracticeScenarioPositions.Select(18,2,731,f,t,128);Need(a.X==b.X&&a.Y==b.Y&&a.RandomState==b.RandomState&&Same(f,beforeF)&&Same(t,beforeT),"Immutable source pools and deterministic seed");
            });
            check("Scenario position trace records strict primary distance and exact terrain retry",delegate{
                var exact=new PracticeScenarioPositionCopy(5,0,731,1);var near=new PracticeScenarioPositionCopy(5,0,731,2);var edge=new PracticeScenarioPositionCopy(5,0,731,3);var terrain=new PracticeScenarioPositionCopy(5,0,731,4);var offset=new PracticeScenarioPositionCopy(5,0,731,5);Need(exact.Result.Attempts.Count>1&&near.Result.Attempts.Count>1&&edge.Result.Attempts.Count==1&&terrain.Result.Attempts.Count>1&&offset.Result.Attempts.Count==1,"Source strict boundaries");Need(exact.Result.Attempts[0].BlockingFleet==20&&terrain.Result.Attempts[0].BlockingTerrain==499&&exact.Result.Attempts[exact.Result.Attempts.Count-1].Accepted,"Diagnostic rejection trace");
            });
            check("Scenario position selection fails clearly at finite modern retry budget",delegate{
                var copy=new PracticeScenarioPositionCopy(5,0,731,1);Need(Reject(delegate{PracticeScenarioPositions.Select(5,0,731,copy.Fleets,copy.Terrain,1);}),"Configured retry limit");Need(Reject(delegate{PracticeScenarioPositions.Select(5,0,731,copy.Fleets,copy.Terrain,0);})&&Reject(delegate{PracticeScenarioPositions.Select(5,0,731,copy.Fleets,copy.Terrain,4097);}),"Budget boundaries");
            });
            check("Scenario position selection rejects uninitialized dispatch and missing base dependencies",delegate{
                var f=new byte[123000];var t=new byte[246000];foreach(int scenario in new[]{0,1,4,9,10,15,16,17,19})Need(Reject(delegate{PracticeScenarioPositions.Select(scenario,0,731,f,t,128);}),"Unsupported dispatch");Need(Reject(delegate{PracticeScenarioPositions.Select(8,2,731,f,t,128);})&&Reject(delegate{PracticeScenarioPositions.Select(18,0,731,f,t,128);})&&Reject(delegate{PracticeScenarioPositions.Select(5,4,731,f,t,128);})&&Reject(delegate{PracticeScenarioPositions.Select(5,0,731,new byte[122999],t,128);})&&Reject(delegate{PracticeScenarioPositions.Select(5,0,731,f,new byte[245999],128);}),"Groups/base/pool extents");
            });
        }
        static void Verify(bool examples)
        {
            Need(OriginalRows.Length==2448,"Original fixture extent");int expectedId=0,visited=0,retried=0,max=0,calls=0;
            foreach(string row in OriginalRows)
            {
                string[] words=row.Split(',');int at=0;Func<long> read=delegate{return long.Parse(words[at++],CultureInfo.InvariantCulture);};int id=checked((int)read()),scenario=checked((int)read()),group=checked((int)read());uint seed=checked((uint)read());int collision=checked((int)read());Need(id==expectedId++,"Original case order");var f=new byte[123000];var t=new byte[246000];int count=checked((int)read());Need(count>=0&&count<=16,"Fixture primary bound");
                for(int n=0;n<count;n++){int slot=checked((int)read()),kind=checked((int)read()),owner=checked((int)read()),x=checked((int)read()),y=checked((int)read()),orientation=checked((int)read());Need(slot>=0&&slot<250&&orientation>=0&&orientation<=4,"Primary fixture fields");int p=slot*492;BitConverter.GetBytes(kind).CopyTo(f,p);BitConverter.GetBytes(checked((short)owner)).CopyTo(f,p+6);BitConverter.GetBytes(checked((short)x)).CopyTo(f,p+12);BitConverter.GetBytes(checked((short)y)).CopyTo(f,p+14);f[p+484]=(byte)orientation;}
                count=checked((int)read());Need(count>=0&&count<=16,"Fixture terrain bound");for(int n=0;n<count;n++){int slot=checked((int)read()),kind=checked((int)read()),x=checked((int)read()),y=checked((int)read());Need(slot>=0&&slot<500,"Terrain fixture fields");int p=slot*492;BitConverter.GetBytes(kind).CopyTo(t,p);BitConverter.GetBytes(checked((short)x)).CopyTo(t,p+12);BitConverter.GetBytes(checked((short)y)).CopyTo(t,p+14);}
                int expectedX=checked((int)read()),expectedY=checked((int)read());uint expectedRandom=checked((uint)read());Need(at==words.Length,"Exact numeric row extent");if(examples&&seed!=731)continue;
                PracticeScenarioPositionResult result;if(examples){var copy=new PracticeScenarioPositionCopy(scenario,group,seed,collision);Need(Same(copy.Fleets,f)&&Same(copy.Terrain,t),"Original-backed copied UI fixture "+id);result=copy.Result;}else result=PracticeScenarioPositions.Select(scenario,group,seed,f,t,128);
                Need(result.X==expectedX&&result.Y==expectedY&&result.RandomState==expectedRandom,"Original position/RNG "+id);visited++;if(result.Attempts.Count>1)retried++;max=Math.Max(max,result.Attempts.Count);calls+=result.RandomCalls;
            }
            Need(visited==(examples?306:2448),"Independent fixture count");if(!examples)Need(retried==1088&&max==17&&calls==7153,"Original corpus retry/RNG coverage");
        }
    }
